package com.nm.fragmentsclean.experienceContext.write.businesslogic.usecases;
import com.nm.fragmentsclean.experienceContext.write.businesslogic.gateways.ExperienceMediaRepository;import com.nm.fragmentsclean.sharedKernel.businesslogic.media.PrivateImageStore;import com.nm.fragmentsclean.sharedKernel.businesslogic.models.DateTimeProvider;import java.time.Duration;
public final class CleanExperienceMediaObjects{private final ExperienceMediaRepository media;private final PrivateImageStore store;private final CompleteExperienceMediaDeletion completion;private final DateTimeProvider clock;private final Duration pendingTtl;public CleanExperienceMediaObjects(ExperienceMediaRepository media,PrivateImageStore store,CompleteExperienceMediaDeletion completion,DateTimeProvider clock,Duration pendingTtl){this.media=media;this.store=store;this.completion=completion;this.clock=clock;this.pendingTtl=pendingTtl;}public void run(int limit){for(var item:media.cleanupCandidates(clock.now().minus(pendingTtl),limit)){var s=item.snapshot();store.delete(s.pendingObjectKey());store.delete(s.objectKey());completion.complete(s.mediaId());}}}
